import{_ as i,o as e,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-10-18","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-10-18","date":"2023-10-18T00:00:00.000Z","updated":"2023-10-19T00:00:00.000Z","tags":["Ceph","RGW","Refactoring","Data Logging","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-10-18.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-10-18.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-10-18.md"};function n(s,t,p,g,a,_){return e(),l("div",null,[...t[0]||(t[0]=[o("<p>在2023年10月18日的Ceph RGW重构会议中，与会人员对数据日志的设计进行了深入讨论。以下是会议的关键要点：</p><p><strong>会议主题</strong>：Ceph数据日志设计讨论</p><p><strong>与会人员</strong>：Adam、Casey、Matt等</p><p><strong>会议内容总结</strong>：</p><ol><li><p><strong>设计讨论</strong>：</p><ul><li>Adam提出了一种新的数据日志设计方案，通过时间戳直接跟踪工作集，以避免竞态条件和数据日志无限增长。</li><li>Casey指出该设计可能存在多目标区域的问题，建议将区域信息存储在数据同步映射中，由trim提供。</li></ul></li><li><p><strong>主要议题</strong>：</p><ul><li><strong>数据日志的替代方案</strong>：讨论了使用omap来跟踪未同步的桶分片，而不是使用数据日志。</li><li><strong>多目标区域的处理</strong>：讨论了如何处理多个目标区域，提出了两种方案。</li><li><strong>优先级和排序问题</strong>：讨论了如何在目标区域中优先处理旧的变更。</li></ul></li><li><p><strong>决定事项</strong>：</p><ul><li>倾向于使用omap来跟踪未同步的桶分片，避免数据日志的无限增长问题。</li><li>讨论了如何在源区域进行排序，以便目标区域可以优先处理旧的变更。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>修改CLS条目以增加时间优先级排序。</li><li>完成REST接口的其余部分。</li><li>考虑数据增量同步的复杂性，以及如何避免向后兼容性问题。</li></ul></li><li><p><strong>其他议题</strong>：</p><ul><li>讨论了rgw账户的设计，提出了一个设计方案，并邀请大家进行评审。</li></ul></li></ol><p><strong>会议结论</strong>：</p><ul><li>会议对数据日志的替代设计方案进行了深入讨论，并提出了具体的实施步骤和后续行动计划。</li><li>对于rgw账户的设计，提出了一个初步的设计方案，并邀请大家进行评审。</li></ul><p><strong>下次会议预告</strong>：</p><ul><li>预计将继续讨论相关设计细节和实施方案。</li></ul>",9)])])}const d=i(r,[["render",n]]);export{c as __pageData,d as default};
